"""Layer 15 MLP hidden unit 1300, seen through its down_proj component.

This component reads almost only one MLP hidden unit (layer 15, unit 1300), so its
activation is that unit's value, scaled. The unit is mostly near zero, but it goes
strongly negative in a few recognisable places, which carry most of the variance:

- a JSON key opener ' {"' (e.g. the arguments object of a tool call): very negative;
- a docstring or annotation tag, 'param' or '@': clearly negative;
- the token right after the end of a list item (',' newline, '",', '":', '_id',
  'self', '///'): moderately negative;
- inside parentheses (argument lists, signatures, calls): a little negative, more
  so on quote tokens.

Everywhere else it sits near zero. Each value is the average activation of its
group, measured on training text. The program is a small rule table, not a model
of the residual stream, and it explains only a few percent of the variance.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

# Tokens that open a JSON key in a tool call's arguments.
JSON_KEY_OPEN = {' {"'}
# Docstring and annotation tags.
TAGS = {"param", " @", "@"}
# Tokens that end a list item: a line break after an argument, a JSON key or value.
ITEM_END = {",\n", '",', '":', '",\n', "_id", "self", " ///"}
# Quote-like tokens that open a string or a name.
QUOTES = {' "', '("', '"'}

# Mean activation of each group, measured on training rows.
JSON_KEY_VALUE = -10.0
TAG_VALUE = -3.5
ITEM_END_VALUE = -1.8
QUOTE_IN_BRACKETS_VALUE = -0.7
IN_BRACKETS_VALUE = -0.14
ELSEWHERE_VALUE = -0.05


def step(carry, prefix, upstream: Mapping):
    tok = prefix.token_strings[-1]
    new_doc = len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if carry is None or new_doc:
        depth, prev = 0, ""
    else:
        depth, prev = carry

    if tok in JSON_KEY_OPEN:
        value = JSON_KEY_VALUE
    elif tok in TAGS:
        value = TAG_VALUE
    elif prev in ITEM_END:
        value = ITEM_END_VALUE
    elif depth > 0 and tok in QUOTES:
        value = QUOTE_IN_BRACKETS_VALUE
    elif depth > 0:
        value = IN_BRACKETS_VALUE
    else:
        value = ELSEWHERE_VALUE

    # Track open parentheses and the previous token for the next position.
    depth = max(0, depth + tok.count("(") - tok.count(")"))
    return (depth, tok), value

"""Layer 15 MLP hidden unit 1301, read as a detector for function-parameter lists in code.

The component is one hidden unit of the layer-15 MLP: its input direction is dominated by
that unit (weight 0.86 of norm 1.1), so its activation is that unit's value times about 1.1.
It is quiet on most text and spikes inside code, most strongly inside the parameter list of
a function or method declaration: at the comma between two parameters, and at the first word
of the next parameter (its type or name), as in `void f(String a, Logger log)`. It is weaker
inside call arguments, a little on declaration lines such as `private Factory factory;`, and
near zero on digits.

The program tracks, token by token, which brackets are open, whether the current line
looks like a declaration, and the last non-space token, and predicts the mean activation
for that context. It explains only a few percent of the variance: the largest spikes sit in
contexts it does not model.
"""

import re

READS = ()

# A declaration keyword or a type name on the current line.
DECL = re.compile(r"\b(def|function|func|fn|void|public|private|protected|static|int|String|char|float|double|bool|class|struct)\b")
WORD = re.compile(r"[A-Za-z_]\w*")

# Mean activation measured on training text, per context.
PARAM, PARAM_START, PARAM_COMMA = 1.0, 2.8, 3.3
CALL, CALL_COMMA = 0.2, 1.2
OTHER, DECL_LINE, PLAIN = 0.05, 0.07, 0.03


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "stack": [], "line": "", "last": ""}
    stack, line, last = carry["stack"], carry["line"], carry["last"]
    token = prefix.token_strings[-1]
    word = token.strip()
    if stack and stack[-1] == "param":
        if word == ",":
            value = PARAM_COMMA
        elif word.isdigit():
            value = 0.2
        elif WORD.fullmatch(word) and last == ",":
            value = PARAM_START
        else:
            value = PARAM
    elif stack and stack[-1] == "call":
        value = CALL_COMMA if word == "," else (0.0 if word.isdigit() else CALL)
    elif stack:
        value = OTHER
    elif DECL.search(line):
        value = DECL_LINE
    else:
        value = PLAIN
    # Update the bracket stack, the current line and the last token with this token.
    for ch in token:
        if ch == "\n":
            line = ""
        elif ch == "(":
            callish = re.search(r"\w$", line) is not None
            if callish and DECL.search(line):
                stack.append("param")
            elif callish:
                stack.append("call")
            else:
                stack.append("bracket")
            line += ch
        elif ch in "[{":
            stack.append("bracket")
            line += ch
        elif ch in ")]}":
            if stack:
                stack.pop()
            line += ch
        else:
            line += ch
    if word:
        last = word
    return {"doc": doc, "stack": stack, "line": line[-200:], "last": last}, value

"""Layer 15 MLP down_proj component 1307: a weak, mostly token-level predictor.

What it does: predicts a small negative value on most tokens, with a strongly negative
value on the chat-format and tool-markup tokens (<|im_start|>, <tool_call>,
<tool_response>, <think>, ...). Within ordinary text it is only slightly more negative
on whitespace, digits and punctuation than on words.

Why: the component's activation (mean -0.05, std 0.32) is spread thinly across contexts.
Its largest reading is a dip on chat-template markup, which the rule captures. Beyond that,
its value is not predicted by token identity or simple token classes: a full per-token
lookup table explains only about 4% of its variance on held-out text.
"""

READS = ()

MARKUP = {
    "<|im_start|>", "<|im_end|>", "<|endoftext|>",
    "<tool_call>", "</tool_call>", "<tool_response>", "</tool_response>",
    "<think>", "</think>",
}
MARKUP_VALUE = -0.8


def token_kind_value(s):
    if s in MARKUP:
        return MARKUP_VALUE
    if s.strip() == "":
        return -0.08
    if s.strip().replace(".", "").replace(",", "").isdigit():
        return -0.07
    if any(ord(c) > 127 for c in s):
        return -0.03
    if s.strip().isalpha():
        return -0.035
    return -0.06


def step(carry, prefix, upstream):
    return carry, token_kind_value(prefix.token_strings[-1])

"""Means-and-method detector for MLP unit 1315 of layer 15 (down_proj).

In plain terms: this unit fires on the word that sets up HOW something is done. Its output
pushes the next-token prediction toward "method / way / using / by" (its output direction,
read through the embeddings, promotes those words). It is strongest at:

- a verb of accomplishing or solving in a passive, right after a be-verb:
  "can be [achieved] by", "is [accomplished] by", "to be [solved] in";
- the means preposition itself: "by", "through", "via", "using";
- Japanese purpose/means markers that introduce a method: には, ため, ために, のは, のに.

Other past participles after a be-verb get a weak positive value. Everything else is 0.
The word lists are the whole program; the unit's activation is otherwise diffuse, so this
explains only a small share of its variance.
"""

ACHIEVE = {
    "achieve", "achieves", "achieved", "achieving", "accomplish", "accomplishes", "accomplished",
    "accomplishing", "solve", "solves", "solved", "solving", "address", "addressed", "obtain",
    "obtained", "reach", "reached", "resolve", "resolved", "overcome", "complete", "completed",
    "perform", "performed", "handle", "handled", "determine", "determined", "calculate",
    "calculated", "compute", "computed", "explain", "explained", "treat", "treated", "describe",
    "described", "fulfill", "fulfilled", "attain", "attained", "tackle", "tackled", "done",
}
READS = ()
BE = {"be", "been", "being", "is", "are", "was", "were", "am"}
MEANS = {"by", "through", "via", "using"}
PURPOSE = {"には", "ため", "ために", "のは", "のに"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = prefix.position > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if word in PURPOSE:
        return carry, 3.4
    if word in MEANS:
        return carry, 1.7
    if word in ACHIEVE:
        return carry, 3.7 if prev in BE else 0.15
    if prev in BE and word.endswith("ed"):
        return carry, 1.0
    return carry, 0.0

"""Category predictor for one MLP down-projection component (layer 15, unit 1322).

Its activation is noisy and is not driven by the current token's identity, so
this program predicts only the average activation for each broad kind of token:
Han characters and kana are most negative, letters and digits are mildly negative,
and punctuation and whitespace sit near zero. The first token of a document is 0.
"""

import regex

READS = ()

# Mean activation of each kind of token, measured on training text.
MEAN = {
    "han": -0.24,
    "kana": -0.15,
    "alpha_space": -0.146,
    "alpha_nospace": -0.112,
    "digit": -0.081,
    "other": -0.094,
    "symbol": -0.069,
    "punct": -0.037,
    "space": -0.017,
}


def kind(text):
    if "�" in text:
        return "other"
    if regex.search(r"\p{Han}", text):
        return "han"
    if regex.search(r"[\p{Hiragana}\p{Katakana}]", text):
        return "kana"
    word = text.strip()
    if word == "":
        return "space"
    if word.isdigit():
        return "digit"
    if regex.fullmatch(r"\p{P}+", word):
        return "punct"
    if regex.fullmatch(r"\p{S}+", word):
        return "symbol"
    if regex.fullmatch(r"[A-Za-z]+", word):
        return "alpha_space" if text[0] == " " else "alpha_nospace"
    return "other"


def step(carry, prefix, upstream):
    if prefix.position == 0:
        return carry, 0.0
    return carry, MEAN[kind(prefix.token_strings[-1])]

"""Label colons: the component fires on the colon that ends a label, heading or key,
where a value or explanation is about to start ("Last updated:", "Publisher:",
"Total time:", "cachedir:", "Written by:"). It is strongest after a word, weaker after
a number (timestamps like 19:05) and weak in file or path references (client.go:676,
foo.py:12). Colon-like separators also fire moderately: a JSON key's ":, a colon that
ends a line, and " =" assignments. Everything else is near 0.

Predicted value = the typical activation for each class, read off the training data.
"""

READS = ()

COLON = (":", "：")


def _previous(prefix):
    # The token before the current one, if it is in the same document, else "".
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return ""
    return prefix.token_strings[-2]


def _colon_value(prev):
    word = prev.strip()
    if word.startswith(".") or "/" in word or "\\" in word:
        return 1.0  # file extension or path: client.go:676, foo.py:12
    if word.isdigit():
        return 2.1  # a number: 19:05, 22:02
    return 3.6  # a word or phrase: "Total time:", "Publisher:"


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    if cur in COLON:
        value = _colon_value(_previous(prefix))
    elif any(c in cur for c in COLON):
        value = 2.3  # ":\n", '":', "):" and similar: a colon glued to other characters
    elif cur == " =":
        value = 0.9  # assignment
    else:
        value = 0.0
    return None, float(value)
